            <FormControl error={!!errorMessage} size="small" sx={{ minWidth }}>
                <Select
                    aria-label={label}
                    disabled={disabled}
                    onChange={onChange}
                    onClose={closeSelect}
                    onOpen={openSelect}
                    size="small"
                    value={value}
                >
                    {children}
                </Select>
            </FormControl>
        </Tooltip>
    )
}
